contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // read balance of this test-contract according to c before deposit
        uint beforeRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        bool reverted;
        // attempt to deposit depositAmount into c as this contract
        c.Deposit{value: depositAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // If the call did not revert, the recorded balance must increase by depositAmount
        // and the contract's ETH balance must increase by depositAmount.
        assert(reverted || (afterRecorded == beforeRecorded + depositAmount && afterContractBal == beforeContractBal + depositAmount));
    }

    // allow receiving ETH so the contract can fund deposits if needed
    receive() external payable {}
}

